const cfg = $('Config').first().json;
const onlyGaps = String(cfg.ONLY_SHOW_GAPS).toLowerCase() === 'true';
const urlTemplate = cfg.EVENT_URL_TEMPLATE || '';
const subjectPrefix = cfg.EMAIL_SUBJECT_PREFIX || 'Event Resourcing Digest';
const excludeStates = String(cfg.EXCLUDE_STATES || '').toLowerCase().split(',').map(function (s) { return s.trim(); }).filter(function (s) { return s; });

// Both queries are paginated, so each node returns one item per page.
const eventsPages = $('Query Events - Resources').all().map(function (i) { return i.json; });
const issuesPages = $('Query Event Issues - Staff').all().map(function (i) { return i.json; });

const errs = [];
for (const pg of eventsPages.concat(issuesPages)) {
  if (pg && pg.errors) { errs.push.apply(errs, pg.errors); }
}
if (errs.length) { throw new Error('Administrate GraphQL returned errors: ' + JSON.stringify(errs)); }

const eventEdges = [];
for (const pg of eventsPages) { eventEdges.push.apply(eventEdges, (((pg || {}).data || {}).events || {}).edges || []); }
const issueEdges = [];
for (const pg of issuesPages) { issueEdges.push.apply(issueEdges, (((pg || {}).data || {}).eventIssues || {}).edges || []); }

const issuesById = {};
for (const e of issueEdges) { issuesById[e.node.id] = e.node; }

function decodeNumeric(id) {
  try { const s = Buffer.from(id, 'base64').toString('utf8'); return (s.split(':')[1]) || id; }
  catch (err) { return id; }
}
function fmt(iso) {
  if (!iso) return '—';
  try { const d = DateTime.fromISO(iso); return d.isValid ? d.toFormat('dd LLL yyyy, HH:mm') : String(iso); }
  catch (err) { return String(iso); }
}
function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const rows = [];
for (const edge of eventEdges) {
  const ev = edge.node;
  const evState = String(ev.lifecycleState || '').toLowerCase();
  if (excludeStates.indexOf(evState) !== -1) { continue; }
  const issue = issuesById[ev.id] || null;
  const issueDataUnavailable = issue === null;
  const issueSessions = (issue && issue.sessions) ? issue.sessions : [];

  const staffByRole = {};
  for (const s of issueSessions) {
    const roles = s.staffRoleFulfillment || [];
    for (const r of roles) {
      const key = r.name || 'Unspecified';
      if (!staffByRole[key]) staffByRole[key] = { type: key, required: 0, booked: 0, missing: 0 };
      staffByRole[key].required += Number(r.numRequired || 0);
      staffByRole[key].booked += Number(r.numBooked || 0);
      staffByRole[key].missing += Number(r.numMissing || 0);
    }
  }
  const personnel = Object.keys(staffByRole).map(function (k) { return staffByRole[k]; });

  const requiredByType = {};
  for (const req of (ev.requiredResources || [])) {
    const tName = (req.resourceType && req.resourceType.name) ? req.resourceType.name : 'Unspecified';
    const nSessions = (req.sessions && req.sessions.length) ? req.sessions.length : 1;
    requiredByType[tName] = (requiredByType[tName] || 0) + Number(req.quantity || 0) * nSessions;
  }

  const missingByType = {};
  for (const s of issueSessions) {
    const mrt = s.missingResourceTypes || [];
    for (const m of mrt) {
      const tName = m.name || 'Unspecified';
      missingByType[tName] = (missingByType[tName] || 0) + Number(m.numMissing || 0);
    }
  }

  const typeNames = {};
  Object.keys(requiredByType).forEach(function (k) { typeNames[k] = true; });
  Object.keys(missingByType).forEach(function (k) { typeNames[k] = true; });
  const resources = Object.keys(typeNames).map(function (name) {
    const required = requiredByType[name] || 0;
    if (issueDataUnavailable) {
      return { type: name, required: required, booked: '—', missing: '—' };
    }
    const missing = missingByType[name] || 0;
    const booked = Math.max(0, required - missing);
    return { type: name, required: required, booked: booked, missing: missing };
  });

  const totalMissingStaff = personnel.reduce(function (a, p) { return a + p.missing; }, 0);
  const totalMissingRes = resources.reduce(function (a, r) { return a + (typeof r.missing === 'number' ? r.missing : 0); }, 0);
  const hasMissing = (totalMissingStaff + totalMissingRes) > 0
    || (issue && issue.hasInstructors === false)
    || (issue && issue.hasAllRequiredResources === false);
  const overStaff = personnel.some(function (p) { return p.booked > p.required; });
  const overRes = resources.some(function (r) { return typeof r.booked === 'number' && r.booked > r.required; });
  const hasOver = overStaff || overRes;
  const flagged = hasMissing || hasOver;

  if (onlyGaps && !flagged) continue;

  const numericId = decodeNumeric(ev.id);
  const link = urlTemplate ? urlTemplate.replace('{id}', numericId) : '';

  rows.push({
    title: ev.title || (issue && issue.title) || '(untitled)',
    code: ev.code || (issue && issue.code) || '',
    start: ev.start || (issue && issue.start) || '',
    end: ev.end || (issue && issue.end) || '',
    location: (ev.location && ev.location.name) || (issue && issue.locationName) || '',
    fillRate: issue ? issue.fillRate : null,
    targetFillRate: issue ? issue.targetFillRate : null,
    link: link,
    personnel: personnel,
    resources: resources,
    hasMissing: !!hasMissing,
    hasOver: !!hasOver,
    flagged: !!flagged
  });
}

rows.sort(function (a, b) {
  const rank = function (x) { return x.hasMissing ? 2 : (x.hasOver ? 1 : 0); };
  const d = rank(b) - rank(a);
  if (d !== 0) return d;
  return String(a.start).localeCompare(String(b.start));
});

if (rows.length === 0) { return []; }

const purple = '#6A3CE3';
const red = '#C0392B';
const amber = '#B26A00';
const green = '#1E8E5A';
const border = '#E3E3E8';
const muted = '#6B6B76';

function cell(v, color) {
  const style = 'padding:4px 8px;border:1px solid ' + border + ';font-size:13px;' + (color ? ('color:' + color + ';font-weight:700;') : '');
  return '<td style="' + style + '">' + esc(v) + '</td>';
}
function th(v) {
  return '<th style="padding:4px 8px;border:1px solid ' + border + ';font-size:12px;text-align:left;background:#F4F1FB;color:' + purple + ';">' + esc(v) + '</th>';
}

let blocks = '';
for (const r of rows) {
  let pRows = '';
  if (r.personnel.length === 0) {
    pRows = '<tr><td colspan="4" style="padding:6px 8px;border:1px solid ' + border + ';font-size:12px;color:' + muted + ';">No personnel requirements.</td></tr>';
  } else {
    for (const p of r.personnel) {
      const bColor = (p.booked > p.required) ? amber : null;
      const mColor = (p.missing > 0) ? red : null;
      pRows += '<tr>' + cell(p.type) + cell(p.required) + cell(p.booked, bColor) + cell(p.missing, mColor) + '</tr>';
    }
  }
  const pTable = '<table style="border-collapse:collapse;margin:6px 0 12px;width:100%;">' +
    '<tr>' + th('Personnel type') + th('Required') + th('Booked') + th('Missing') + '</tr>' + pRows + '</table>';

  let rRows = '';
  if (r.resources.length === 0) {
    rRows = '<tr><td colspan="4" style="padding:6px 8px;border:1px solid ' + border + ';font-size:12px;color:' + muted + ';">No resource requirements.</td></tr>';
  } else {
    for (const res of r.resources) {
      const bColor = (typeof res.booked === 'number' && res.booked > res.required) ? amber : null;
      const mColor = (typeof res.missing === 'number' && res.missing > 0) ? red : null;
      rRows += '<tr>' + cell(res.type) + cell(res.required) + cell(res.booked, bColor) + cell(res.missing, mColor) + '</tr>';
    }
  }
  const rTable = '<table style="border-collapse:collapse;margin:6px 0 4px;width:100%;">' +
    '<tr>' + th('Resource type') + th('Required') + th('Booked') + th('Missing') + '</tr>' + rRows + '</table>';

  const titleHtml = r.link
    ? '<a href="' + esc(r.link) + '" style="color:' + purple + ';text-decoration:none;">' + esc(r.title) + '</a>'
    : esc(r.title);

  let badge;
  let barColor;
  if (r.hasMissing) {
    badge = '<span style="background:' + red + ';color:#fff;font-size:11px;padding:2px 8px;border-radius:10px;margin-left:8px;">ACTION NEEDED</span>';
    barColor = red;
  } else if (r.hasOver) {
    badge = '<span style="background:' + amber + ';color:#fff;font-size:11px;padding:2px 8px;border-radius:10px;margin-left:8px;">OVER-BOOKED</span>';
    barColor = amber;
  } else {
    badge = '<span style="background:' + green + ';color:#fff;font-size:11px;padding:2px 8px;border-radius:10px;margin-left:8px;">OK</span>';
    barColor = purple;
  }

  const fill = (r.fillRate != null) ? (' &nbsp;·&nbsp; Fill: ' + r.fillRate + '%' + (r.targetFillRate != null ? ' / target ' + r.targetFillRate + '%' : '')) : '';

  blocks += '<div style="border:1px solid ' + border + ';border-left:4px solid ' + barColor + ';border-radius:6px;padding:12px 14px;margin:0 0 16px;">' +
    '<div style="font-size:15px;font-weight:700;color:#1B1B1F;">' + titleHtml + (r.code ? ' <span style="color:' + muted + ';font-weight:400;font-size:12px;">(' + esc(r.code) + ')</span>' : '') + badge + '</div>' +
    '<div style="font-size:12px;color:' + muted + ';margin:4px 0 2px;">' + fmt(r.start) + ' → ' + fmt(r.end) + ' &nbsp;·&nbsp; ' + esc(r.location || 'No location') + fill + '</div>' +
    pTable + rTable + '</div>';
}

const flaggedCount = rows.filter(function (r) { return r.flagged; }).length;
const dateLabel = DateTime.now().toFormat('dd LLL yyyy');
const html = '<div style="font-family:Inter,Arial,sans-serif;max-width:760px;margin:0 auto;color:#1B1B1F;">' +
  '<h2 style="color:' + purple + ';margin:0 0 4px;">Event Resourcing Digest</h2>' +
  '<div style="font-size:13px;color:' + muted + ';margin:0 0 16px;">' + dateLabel + ' &nbsp;·&nbsp; ' + rows.length + ' active event(s) in the next ' + esc(cfg.WINDOW_DAYS) + ' days &nbsp;·&nbsp; ' + flaggedCount + ' need attention</div>' +
  blocks +
  '<div style="font-size:11px;color:' + muted + ';margin-top:12px;">Figures are per session (a requirement across N sessions counts as N slots). Missing (red) comes from Administrate resourcing checks; Booked = Required − Missing. Booked shown in amber when it exceeds Required (over-booked).</div>' +
  '</div>';

return [{ json: {
  subject: subjectPrefix + ' — ' + dateLabel + ' (' + rows.length + ' events, ' + flaggedCount + ' need attention)',
  recipients: cfg.RECIPIENTS,
  eventCount: rows.length,
  flaggedCount: flaggedCount,
  html: html
} }];
